#!/usr/bin/env python3
"""
TSL to Test Case Generator
Parses TSL specification and generates test cases using Category-Partition Method
"""

import json
import re
from collections import defaultdict

def parse_tsl(filename):
    """Parse TSL file and extract categories, choices, and annotations"""
    with open(filename, 'r') as f:
        content = f.read()

    # Split into Parameters and Environments sections
    parts = content.split('\n\n')
    param_section = None
    env_section = None

    for part in parts:
        if part.startswith('Parameters:'):
            param_section = part
        elif part.startswith('Environments:'):
            env_section = part

    def parse_category_block(block):
        """Parse a category block (lines under a category header)"""
        categories = []
        lines = block.strip().split('\n')
        current_cat = None
        current_choices = []

        for line in lines:
            line = line.strip()
            if not line:
                continue

            # Check if this is a category header (has choices indented under it)
            if line.endswith(':') and not line.startswith('    '):
                # This is a category header
                if current_cat is not None:
                    categories.append((current_cat, current_choices))
                current_cat = line[:-1]  # Remove trailing colon
                current_choices = []
            elif line.startswith('        ') and current_cat is not None:
                # This is a choice (indented)
                # Parse the choice line
                # Format: choice_text [annotations...]
                annotations = []
                # Remove annotations
                choice_text = line
                # Find annotations in brackets
                ann_matches = re.findall(r'\[([^\]]+)\]', line)
                for ann in ann_matches:
                    annotations.append(ann.strip())
                choice_text = re.sub(r'\[[^\]]+\]', '', line).strip()
                current_choices.append({
                    'text': choice_text,
                    'annotations': annotations
                })

        if current_cat is not None:
            categories.append((current_cat, current_choices))

        return categories

    def parse_section(section_text):
        """Parse a section (Parameters or Environments)"""
        if not section_text:
            return []
        return parse_category_block(section_text)

    all_categories = []
    if param_section:
        all_categories.extend(parse_section(param_section))
    if env_section:
        all_categories.extend(parse_section(env_section))

    return all_categories

def parse_annotation(ann_str):
    """Parse an annotation string like 'property LocalSource' or 'if LocalSource or RemoteSource'"""
    ann = ann_str.strip()
    if ann.startswith('if '):
        condition = ann[3:].strip()
        return {'type': 'if', 'condition': condition}
    elif ann.startswith('property '):
        prop = ann[9:].strip()
        return {'type': 'property', 'value': prop}
    elif ann == 'error':
        return {'type': 'error'}
    elif ann == 'single':
        return {'type': 'single'}
    else:
        return {'type': 'unknown', 'value': ann}

def get_all_annotations(choices):
    """Get all annotations from a list of choices"""
    props = []
    errors = []
    singles = []
    conditions = []

    for choice in choices:
        for ann in choice.get('annotations', []):
            parsed = parse_annotation(ann)
            if parsed['type'] == 'property':
                props.append(parsed['value'])
            elif parsed['type'] == 'error':
                errors.append(choice)
            elif parsed['type'] == 'single':
                singles.append(choice)
            elif parsed['type'] == 'if':
                conditions.append((choice, parsed['condition']))

    return {
        'props': props,
        'errors': errors,
        'singles': singles,
        'conditions': conditions
    }

def condition_satisfied(condition, chosen_props, chosen_values):
    """Check if a condition is satisfied by current choices"""
    cond = condition.strip()
    # Handle 'and', 'or' conditions
    if ' and ' in cond:
        parts = cond.split(' and ')
        return all(condition_satisfied(p.strip(), chosen_props, chosen_values) for p in parts)
    elif ' or ' in cond:
        parts = cond.split(' or ')
        return any(condition_satisfied(p.strip(), chosen_props, chosen_values) for p in parts)
    else:
        # Single property check
        return cond.strip() in chosen_props

def generate_test_cases(categories):
    """Generate test cases from TSL categories"""
    test_cases = []
    tc_id = 1

    # First, identify all error choices and single choices that must be included
    error_choices = []
