    # Build a map of property to where it's defined
    property_definitions = defaultdict(list)  # prop -> list of (category, choice_idx)

    for cat_name, choices in categories:
        anns = get_all_annotations(choices)
        for choice in choices:
            for ann in choice.get('annotations', []):
                parsed = parse_annotation(ann)
                if parsed['type'] == 'property':
                    property_definitions[parsed['value']].append((cat_name, len(choices)-1))
                elif parsed['type'] == 'error':
                    error_choices.append((cat_name, choices.index(choice), choice))
                elif parsed['type'] == 'single':
                    single_choices.append((cat_name, choices.index(choice), choice))
                elif parsed['type'] == 'if':
                    pass  # Condition, handled during generation

    # Strategy: Generate test cases by systematically combining choices
    # We'll create a set of test frames that cover requirements

    # Helper to get valid choices for a category given current frame
    def get_valid_choices(category_idx, current_frame, current_props):
        """Get choices that are valid given current frame state"""
