Uses Category-Partition Method to generate test frames
"""

import json
from collections import defaultdict

def parse_tsl(filename):
    """Parse TSL file into structured format"""
    with open(filename, 'r') as f:
        lines = f.readlines()

    categories = []
    current_category = None
    current_choices = []

    for line in lines:
        line = line.rstrip()

        # Skip empty lines and comments
        if not line.strip() or line.strip().startswith('#'):
            if current_category is not None:
                categories.append((current_category, current_choices))
                current_category = None
                current_choices = []
            continue

        # Section header
        if line.strip() in ('Parameters:', 'Environments:'):
            continue

        # Category header (4 spaces, ends with colon)
        if line.startswith('    ') and not line.startswith('        ') and line.endswith(':'):
            if current_category is not None:
                categories.append((current_category, current_choices))
            current_category = line.strip()[:-1]
            current_choices = []
            continue

        # Choice (8 spaces)
        if line.startswith('        '):
            annotations = []
            ann_matches = re.findall(r'\[([^\]]+)\]', line)
            for ann in ann_matches:
                annotations.append(ann.strip())
            choice_text = re.sub(r'\[[^\]]+\]', '', line).strip()
            current_choices.append({
                'text': choice_text,
                'annotations': annotations
            })

    if current_category is not None:
        categories.append((current_category, current_choices))

    return categories

import re

def parse_annotation(ann_str):
    """Parse annotation string"""
    ann = ann_str.strip()
    if ann.startswith('if '):
        return {'type': 'if', 'condition': ann[3:].strip()}
    elif ann.startswith('property '):
        return {'type': 'property', 'value': ann[9:].strip()}
    elif ann == 'error':
        return {'type': 'error'}
    elif ann == 'single':
        return {'type': 'single'}
    else:
        return {'type': 'unknown', 'value': ann}

def condition_satisfied(condition, satisfied_props):
    """Check if condition is satisfied"""
    cond = condition.strip()
    if ' and ' in cond:
        parts = cond.split(' and ')
        return all(condition_satisfied(p.strip(), satisfied_props) for p in parts)
    elif ' or ' in cond:
        parts = cond.split(' or ')
        return any(condition_satisfied(p.strip(), satisfied_props) for p in parts)
    else:
        return cond.strip() in satisfied_props

def get_choice_annotations(choices):
    """Extract annotations from choices"""
    result = {
        'properties': [],
        'errors': [],
        'singles': [],
        'conditions': []  # (choice_idx, condition_string)
    }
    for i, choice in enumerate(choices):
        for ann in choice.get('annotations', []):
            parsed = parse_annotation(ann)
            if parsed['type'] == 'property':
                result['properties'].append((i, parsed['value']))
            elif parsed['type'] == 'error':
                result['errors'].append(i)
            elif parsed['type'] == 'single':
                result['singles'].append(i)
            elif parsed['type'] == 'if':
                result['conditions'].append((i, parsed['condition']))
    return result

def is_choice_valid(choice_annotations, frame_props):
    """Check if a choice is valid given current frame properties"""
    for idx, cond in choice_annotations['conditions']:
        if not condition_satisfied(cond, frame_props):
            return False
    return True

def generate_test_cases():
