        }
    )

    # Error: destination locked (Concurrent operations)
    add_tc(
        {"Concurrent operations": "destination locked"},
        "Test: Destination file is locked",
        "error",
        {
            "source": "/local/file.txt",
            "destination": "/local/file.txt",
            "command": "distributed_file_sync /local/file.txt /local/file.txt",
