        {
            "source": "/local/lockedfile.txt",
            "destination": "/local/dest/",
            "command": "distributed_file_sync /local/lockedfile.txt /local/dest/",
            "expected_error": "Source file is locked by another process"
        }
    )

    print(f"Generated {len(test_cases)} test cases (including errors)")

    return test_cases, categories, cat_annotations

